// Writes the public pages, sitemap.xml, llms.txt and llms-full.txt from
// site/. Vercel runs no build: the generated files are committed, and
// test/build.test.js fails while any of them differs from what build()
// returns, so what is committed is still what is deployed.
//
//   npm run build            build into the tree, then stamp
//   node scripts/build.js --out <dir>   build into another folder, unstamped (previews)

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { SITE, PAGES } from "../site/site.js";
import { sitemap, llms, llmsFull } from "../site/machine.js";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");

export const banner = (source) =>
  `<!-- Generated by scripts/build.js from ${source}. Edit that, then run npm run build. -->\n`;

// Pure: the same site/ always gives the same Map of repo path to text.
export async function build() {
  const out = new Map();
  const rendered = [];
  for (const page of PAGES) {
    // While the rebuild is in progress some pages have no source yet.
    if (!existsSync(path.join(ROOT, "site/pages", page.id + ".js"))) continue;
    const mod = await import(`../site/pages/${page.id}.js`);
    const doc = String(mod.render(page, SITE));
    if (!doc.startsWith("<!doctype html>")) throw new Error(`site/pages/${page.id}.js must return a whole document`);
    out.set(page.file, doc.replace("<!doctype html>\n", "<!doctype html>\n" + banner(`site/pages/${page.id}.js`)));
    rendered.push({ page, text: mod.text ? mod.text(page, SITE) : "" });
  }
  out.set("sitemap.xml", sitemap(SITE, PAGES));
  out.set("llms.txt", llms(SITE, PAGES));
  out.set("llms-full.txt", llmsFull(SITE, rendered));
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const at = process.argv.indexOf("--out");
  const dest = at > 0 ? path.resolve(process.argv[at + 1]) : ROOT;
  const files = await build();
  for (const [file, text] of files) {
    mkdirSync(path.dirname(path.join(dest, file)), { recursive: true });
    writeFileSync(path.join(dest, file), text);
  }
  console.log(`Built ${files.size} files into ${path.relative(process.cwd(), dest) || "."}`);
}
